enum MenuCallId {
    MC_SHOW,
    MC_SET_BLACK,
    MC_FIND_PICTURE,
    MC_TITLE_RESIZE_MIN,
    MC_TITLE_RESIZE_FIT,
    MC_IS_SHOWN,
    MC_COUNT
};

// a Menu function: the target of the call at a found site + offset words, or (fixed) the function that sits
// offset words from an earlier one in this list; its own window must match there
struct MenuCall {
    const char *name;
    bool fixed;
    int anchor; // MenuPatternId, or MenuCallId when fixed
    int16_t offset;
    MenuPatternId verify;
};

